<script setup>
import {computed} from 'vue'
import DeviceArt from './illustrations/DeviceArt.vue'
import {equipmentArt} from '../data/equipmentPresentation'
const props=defineProps({services:{type:Array,default:()=>[]},modelValue:{type:String,default:''}})
const emit=defineEmits(['update:modelValue'])
const categories=computed(()=>[...new Set(props.services.map(s=>s.equipment_category))].map(name=>({name,count:props.services.filter(s=>s.equipment_category===name).length})))
</script>
<template><section class="category-browser" aria-label="Категории услуг"><div class="category-browser-head"><div><span class="admin-visual-eyebrow">КАТАЛОГ ПО ТЕХНИКЕ</span><h2>У каждой задачи — свой инструмент</h2></div><button v-if="modelValue" @click="emit('update:modelValue','')" type="button">Все категории →</button><span v-else>{{categories.length}} категорий</span></div><div class="category-browser-grid"><button v-for="c in categories" :key="c.name" :aria-pressed="modelValue===c.name" :class="{selected:modelValue===c.name}" type="button" @click="emit('update:modelValue',modelValue===c.name?'':c.name)"><span><DeviceArt :name="equipmentArt(c.name)"/></span><div><strong>{{c.name}}</strong><small>{{c.count}} {{c.count===1?'услуга':c.count<5?'услуги':'услуг'}}</small></div><i v-if="modelValue===c.name">✓</i></button></div></section></template>
<style scoped>.category-browser{border:1px solid var(--border);border-radius:22px;background:radial-gradient(ellipse at top right,color-mix(in srgb,var(--blue) 6%,transparent),transparent 65%),var(--surface);padding:24px}.category-browser-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.category-browser h2{font-size:22px;font-weight:720;letter-spacing:-.03em;margin-top:7px}.category-browser-head>span,.category-browser-head>button{font-size:13px;color:var(--muted);white-space:nowrap}.category-browser-head>button{color:var(--blue);cursor:pointer}.category-browser-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.category-browser-grid>button{display:flex;align-items:center;gap:12px;position:relative;padding:13px;background:var(--bg);border:1px solid var(--border);border-radius:15px;text-align:left;transition:border-color .2s,transform .2s;cursor:pointer}.category-browser-grid>button:hover{border-color:var(--blue);transform:translateY(-2px)}.category-browser-grid>button.selected{border-color:var(--blue);background:color-mix(in srgb,var(--blue) 6%,var(--surface))}.category-browser-grid>button>span{width:50px;height:50px;flex-shrink:0}.category-browser-grid strong{font-size:13px;font-weight:650;line-height:1.4;display:block}.category-browser-grid small{font-size:12px;color:var(--muted);display:block;margin-top:5px}.category-browser-grid i{position:absolute;right:7px;top:3px;color:var(--blue);font-size:12px;font-style:normal}@media(max-width:1100px){.category-browser-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.category-browser{padding:19px}.category-browser-head{align-items:start}.category-browser h2{font-size:20px}.category-browser-head>span{display:none}.category-browser-grid{gap:8px}.category-browser-grid>button{padding:11px 8px;gap:7px;flex-direction:column;align-items:start}.category-browser-grid>button>span{width:43px;height:43px}.category-browser-grid strong{font-